        url=a[i].attr("href")
        size=0.4;
  //url=String(url).replace("1","{{page}}")
        push(title,url,size)
    };
    push("分类",null,1)
    for(i in b){
        title=b[i].text()
        url=b[i].attr("href")
        size=0.25
        if (url.endsWith("sort/")) {
            url=url+"1"
            url=String(url).replace("1","{{page}}")
            push(title,url,size)
        } else if (url.endsWith("sort/1/1/")) {
            url=String(url).replace(url,"sort/1/{{page}}")
            push(title,url,size)
        } else {
            url=String(url).replace("1","{{page}}")
            push(title,url,size)
    }}
      } else { 
      java.toast("🚫发现获取失败……");
}
JSON.stringify(result);

