function getImgList() {
var str = html.match(/murl_e=\"(.*?)\"/)[1];
var list = window.atob(str).split("\\$qingtiandy\\$");
if(list[0].substr(0,4)=="http"){
return list;
}
var piclist = new Array([list.length]);
for (var i = 0; i < list.length; i++) {
piclist[i] = "http://www.xatxwh.com" + list[i];
}
return piclist;
}@Header:{Referer:host}

